import { lazy, Suspense, type ReactNode } from "react";

export type ThemeName = "augur";

export const themeNames: ThemeName[] = ["augur"];

export type KcEnvName = "ORG_NAME" | "ORG_LOGO_URL";

export const kcEnvNames: KcEnvName[] = ["ORG_NAME", "ORG_LOGO_URL"];

